func joinWithSep(parts []string, sep string) string {
	if len(parts) == 0 {
		return ""
	}
	var b strings.Builder
	for i, p := range parts {
		if i > 0 {
			b.WriteString(sep)
		}
		b.WriteString(p)
	}
	return b.String()
}

func repeatStr(s string, n int) string {
	var b strings.Builder
	b.Grow(len(s) * n)
	for i := 0; i < n; i++ {
		b.WriteString(s)
	}
	return b.String()
}

type Employee struct {
	Name   string
	Salary float64
}

type BySalary []Employee

func (s BySalary) Len() int           { return len(s) }
func (s BySalary) Less(i, j int) bool  { return s[i].Salary < s[j].Salary }
func (s BySalary) Swap(i, j int)       { s[i], s[j] = s[j], s[i] }

func topEarners(employees []Employee, n int) []Employee {
	sorted := make([]Employee, len(employees))
	copy(sorted, employees)
	sort.Sort(sort.Reverse(BySalary(sorted)))
	if n > len(sorted) {
		n = len(sorted)
	}
	return sorted[:n]
}

